import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Programming and Data Structures → Trees and BSTs; Binary heaps. Numbers from lib/study/pds.ts, checked by script:
 * Height 3 (edges): max 15 nodes, min 4, 8 leaves when perfect; 10 nodes: min height 3, max 9, 16 796 shapes (Catalan 10).
 * Pre A B D E C F G + in D B E A F C G → post D E B F G C A, level A B C D E F G, height 2. Pre 1 2 4 5 3 6 + in 4 2 5 1 6 3 → post 4 5 2 6 3 1.
 * BST insert 50 30 70 20 40 60 80 35: pre 50 30 20 40 35 70 60 80, height 3, 4 leaves, 13 comparisons; delete 30 → pre 50 35 20 40 70 60 80.
 * AVL insert 10 20 30 40 50 25: RR at 10, RR at 30, RL at 20 → root 30, height 2, pre 30 20 10 25 40 50. 1..7 → height 2. Min nodes N(3) 7, N(4) 12, N(5) 20.
 * Max-heap: insert 10 20 15 30 40 one by one → 40 30 15 10 20 (5 swaps); build-heap → same array, 3 swaps; delete-max → 30 20 15 10 (1 swap).
 * Heapsort 4 10 3 5 1: heap 10 5 3 4 1, passes 5 4 3 1 | 10; 4 1 3 | 5 10; 3 1 | 4 5 10; 1 | 3 4 5 10.
 * Distinct-key max-heaps: n = 3 → 2, 4 → 3, 5 → 8, 6 → 20, 7 → 80, 10 → 3360. 3-ary heap index 4: parent 1, children 13 14 15; 40 keys → height 3.
 */
const DS = "/topics/data-structures";

